# -*- coding: utf-8 -*-
import os

from taf.playwright.core.artifacts import ArtifactManager
from taf.playwright.core.browser import BrowserManager
from taf.playwright.core.debug import catch_interface_exception
from taf.playwright.core.session import SessionStore
from taf.playwright.sbts.provider import Provider


class sbts(object):
    """Robot Framework entry point for the Playwright SBTS backend."""

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    DOWNLOAD_DIR_SUFFIX = "taf_playwright_sbts_download"
    SCREENSHOT_DIR_SUFFIX = "taf_playwright_sbts_screenshot"

    def __init__(self, browser_manager_factory=None, provider=None, session_store=None):
        self._browser_manager_factory = browser_manager_factory or BrowserManager
        self._provider = provider or Provider
        self._sessions = session_store or SessionStore()
        self._download_dir = None
        self._screenshot_dir = None
        self._artifacts = ArtifactManager(self.DOWNLOAD_DIR_SUFFIX, self.SCREENSHOT_DIR_SUFFIX)

    @property
    def download_dir(self):
        return self._download_dir

    @property
    def screenshot_dir(self):
        return self._screenshot_dir

    @catch_interface_exception
    def login(self, url, username, password, timeout=60, download_dir=None, screenshot_dir=None, version="SBTS26R3",
              browser="chromium", alias=None, headless=True, port=443, ssl=True, readonly=False, trace_dir=None,
              slow_mo=None, modal_action_configurations=None, ignore_https_errors=True, channel=None, proxy=None,
              record_video_dir=None):
        """Login into SBTS Web UI with a Playwright browser session.

        `modal_action_configurations` is accepted for API compatibility with
        `taf.selenium.sbts`; the first Playwright skeleton handles only the
        common post-login modals in the page object.
        """
        del modal_action_configurations
        self._configure_artifact_dirs(download_dir, screenshot_dir)
        manager = self._browser_manager_factory(
            browser=browser,
            headless=headless,
            download_dir=self._download_dir,
            trace_dir=trace_dir,
            slow_mo=slow_mo,
            ignore_https_errors=ignore_https_errors,
            channel=channel,
            proxy=proxy,
            record_video_dir=record_video_dir,
        )
        browser_session = manager.create_session()
        sbts_cls = self._provider.provide(version)
        sbts_obj = sbts_cls(browser_session, self._screenshot_dir)
        login_msg = sbts_obj.login(
            url=url,
            username=username,
            password=password,
            port=port,
            ssl=ssl,
            timeout=timeout,
            readonly=readonly,
        )
        self._sessions.add(sbts_obj, alias)
        return login_msg

    @catch_interface_exception
    def logout(self, timeout=10, sbts=None, close_browser=True):
        """Logout from SBTS and optionally close the Playwright browser session."""
        target = self._sessions.get(sbts)
        target.logout(timeout=int(timeout))
        if self._to_bool(close_browser):
            self._sessions.remove(sbts)
            target.close()

    @catch_interface_exception
    def get_bts_status(self, timeout=5, sbts=None, technology=None):
        """Return BTS status text from the active SBTS session."""
        return self._sessions.get(sbts).get_bts_status(timeout=int(timeout), technology=technology)

    @catch_interface_exception
    def save_screenshot(self, filename, screenshot_dir=None, sbts=None):
        """Save a full-page screenshot for the active SBTS session."""
        return self._sessions.get(sbts).save_screenshot(filename, screenshot_dir)

    @catch_interface_exception
    def go_to_configuration(self, timeout=60, sbts=None):
        """Navigate to the SBTS Configuration domain."""
        return self._sessions.get(sbts).configuration.navigate_to(timeout=int(timeout))

    @catch_interface_exception
    def go_to_commissioning_tab(self, target_tab_path, timeout=60, sbts=None):
        """Navigate to a target path under the SBTS Commissioning Wizard."""
        return self._sessions.get(sbts).commissioning.go_to_target_path_under_commissioning_tab(
            target_tab_path,
            timeout=int(timeout),
        )

    @catch_interface_exception
    def go_to_diagnostic(self, timeout=60, sbts=None):
        """Navigate to the SBTS Diagnostic domain."""
        return self._sessions.get(sbts).diagnostic.navigate_to(timeout=int(timeout))

    @catch_interface_exception
    def go_to_software(self, timeout=60, sbts=None):
        """Navigate to the SBTS Software domain."""
        return self._sessions.get(sbts).software.navigate_to(timeout=int(timeout))

    @catch_interface_exception
    def go_to_alarms(self, timeout=60, sbts=None):
        """Navigate to the SBTS Alarms domain."""
        return self._sessions.get(sbts).alarms.navigate_to(timeout=int(timeout))

    @catch_interface_exception
    def go_to_performance(self, timeout=60, sbts=None):
        """Navigate to the SBTS Performance domain."""
        return self._sessions.get(sbts).performance.navigate_to(timeout=int(timeout))

    @catch_interface_exception
    def close_all(self):
        """Close all stored Playwright SBTS sessions."""
        self._sessions.close_all()

    def list_aliases(self):
        """Return the currently registered SBTS aliases."""
        return self._sessions.aliases()

    @catch_interface_exception
    def login_with_offline_mode(self, file_path, timeout=60, download_dir=None, screenshot_dir=None,
                                version="SBTS26R3", browser="chromium", alias=None, headless=True,
                                trace_dir=None, slow_mo=None):
        """Open a local SBTS/WebEM HTML file under offline mode."""
        self._configure_artifact_dirs(download_dir, screenshot_dir)
        manager = self._browser_manager_factory(
            browser=browser,
            headless=headless,
            download_dir=self._download_dir,
            trace_dir=trace_dir,
            slow_mo=slow_mo,
        )
        browser_session = manager.create_session()
        sbts_cls = self._provider.provide(version)
        sbts_obj = sbts_cls(browser_session, self._screenshot_dir)
        sbts_obj.page.goto("file:///" + os.path.abspath(file_path).replace("\\", "/"),
                           wait_until="domcontentloaded",
                           timeout=int(float(timeout) * 1000))
        self._sessions.add(sbts_obj, alias)

    def _configure_artifact_dirs(self, download_dir=None, screenshot_dir=None):
        self._download_dir = self._resolve_download_dir(download_dir)
        self._screenshot_dir = self._resolve_screenshot_dir(screenshot_dir)

    @staticmethod
    def _ensure_dir(target):
        if not os.path.exists(target):
            os.makedirs(target)
        return target

    def _resolve_download_dir(self, download_dir=None):
        return self._artifacts.download_dir(download_dir)

    def _resolve_screenshot_dir(self, screenshot_dir=None):
        return self._artifacts.screenshot_dir(self._download_dir, screenshot_dir)

    @staticmethod
    def _to_bool(value):
        if isinstance(value, bool):
            return value
        return str(value).strip().lower() not in ("false", "0", "no", "off")
